// Exclusive dragon avatar frame. Shown only for the owner's Google account.
(function(){
const OWNER='gemy1gg@gmail.com',IMG='data:image/png;base64,';
function mine(){try{const g=JSON.parse(localStorage.getItem('tk_g')||'null');return !!(g&&g.email&&String(g.email).toLowerCase()===OWNER)}catch(e){return false}}
const st=document.createElement('style');
st.textContent='.vip-ring{position:fixed;left:0;top:0;pointer-events:none;z-index:46;background:url('+IMG+') center/100% 100% no-repeat;filter:drop-shadow(0 0 6px #3b82f6aa);display:none;animation:vipGlow 2.6s ease-in-out infinite}@keyframes vipGlow{50%{filter:drop-shadow(0 0 12px #60a5fa) drop-shadow(0 0 4px #fbbf24)}}';
document.head.appendChild(st);
const pool=[];let on=false;
function ring(i){if(!pool[i]){const d=document.createElement('div');d.className='vip-ring';document.body.appendChild(d);pool[i]=d}return pool[i]}
function vis(el){if(!el.getClientRects().length)return false;const cs=getComputedStyle(el);return cs.display!=='none'&&cs.visibility!=='hidden'}
function tick(){
 const m=mine();let i=0;
 if(m){const q=document.querySelectorAll('#globalAvatar,#hmAcc,.acc-av,#avatarPreview,.greeting-avatar,.greeting-emoji');
  q.forEach(el=>{if(!vis(el))return;const r=el.getBoundingClientRect();if(r.width<12)return;
   const d=Math.min(r.width,r.height),cx=r.left+r.width/2,cy=r.top+r.height/2,vw=document.documentElement.clientWidth;let s=d/0.62*0.97;s=Math.min(s,2*cx-4,2*(vw-cx)-4,(cy-2)/0.555);if(s<d)s=d;
   const g=ring(i++);g.style.display='block';g.style.width=g.style.height=s+'px';g.style.transform='translate('+(cx-s/2+s*0.008)+'px,'+(cy-s/2-s*0.055)+'px)'})}
 for(;i<pool.length;i++)pool[i].style.display='none';
 requestAnimationFrame(tick)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',tick);else tick();
})();
